<div class="sl-head"><div><h1 class="sl-title">Customer delivery requests</h1><p class="sl-lede">Approved delivery prices, verified destinations and one rider per request.</p></div><?php if(!dl_agency()&&$user->cdp_hasPermission(['manage_freight','manage_rider_fees'])): ?><a class="sl-btn ghost" href="delivery_settings.php">Pricing, Maps and zones</a><?php endif; ?></div>
<?php if(!$d['ready']): ?><div class="sl-banner warn">Install the courier delivery database migration.</div><?php return;endif; ?>
<?php if(!empty($d['notFound'])): ?><div class="sl-banner bad">Request not found in your agency.</div><?php endif; ?>
<?php if($d['request']):$r=$d['request'];include __DIR__.'/partials/delivery_summary.php'; ?>
<?php if(in_array($r->state,['pending','assigned','failed'],true)): ?><form class="sl-card row wrap g12" data-sl-form data-sl-redirect action="ajax/sl/delivery_ajax.php" method="post"><input type="hidden" name="op" value="assign"><input type="hidden" name="id" value="<?= (int)$r->id ?>"><label class="sl-field grow"><span class="sl-lab">Assign or reassign a rider</span><select class="sl-in" name="driver_id" required><option value="">Choose a rider</option><?php foreach($d['riders'] as $rider):if($r->agency_id&&(int)$rider->agency_id!==(int)$r->agency_id)continue; ?><option value="<?= (int)$rider->id ?>"><?= h($rider->name) ?></option><?php endforeach; ?></select></label><button class="sl-btn" type="submit">Assign delivery</button><button class="sl-btn ghost" type="button" data-sl-action="ajax/sl/delivery_ajax.php" data-p-op="cancel" data-p-id="<?= (int)$r->id ?>" data-sl-confirm="Cancel this delivery request?" data-sl-reload>Cancel request</button></form><?php endif; if ($r->state==='onroute'): ?><form class="sl-card col g12" data-sl-form data-sl-redirect action="ajax/sl/delivery_ajax.php" method="post"><input type="hidden" name="op" value="cancel"><input type="hidden" name="id" value="<?= (int)$r->id ?>"><label class="sl-field"><span class="sl-lab">Recall / cancel reason (confirm parcel custody with the rider first)</span><input class="sl-in" name="note" minlength="3" maxlength="500" required></label><button class="sl-btn ghost" type="submit">Recall and cancel delivery</button></form><?php endif;endif; ?>
<nav class="sl-seg boxed" aria-label="Delivery status"><?php foreach(['open','pending','assigned','onroute','failed','delivered','cancelled','all'] as $state): ?><a class="<?= ($d['filter']??'')===$state?'on':'' ?>" href="delivery_dispatch.php?state=<?= h($state) ?>"><?= h(ucfirst($state)) ?></a><?php endforeach; ?></nav>
<section class="sl-card flush"><div class="sl-tw"><table class="sl-table"><thead><tr><th>Request</th><th>Contact / destination</th><th>Parcels</th><th>Fee / collection</th><th>Rider</th><th>Status</th></tr></thead><tbody><?php foreach($d['requests'] as $r): ?><tr><td><a class="sl-btn ghost sm" href="delivery_dispatch.php?id=<?= (int)$r->id ?>">#<?= (int)$r->id ?></a></td><td class="wrap"><?= h($r->contact_name) ?><br><?= h($r->address) ?></td><td><?= count(json_decode($r->parcel_json,true)?:[]) ?> <?= h($r->module) ?></td><td><?= h(dl_money((int)$r->amount_cents,$r->currency)) ?><br><?= $r->fee_collected?'Collected':'Outstanding' ?></td><td><?= h($r->rider_name?:'Needs dispatch') ?></td><td><?= h($r->state) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$d['requests']): ?><div class="sl-empty">No delivery requests in this view.</div><?php endif; ?></section>
